package com.tamir.drift.feedback

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.SoundPool
import com.tamir.drift.R
import com.tamir.drift.data.settings.SettingsStore
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch
import java.util.concurrent.ConcurrentHashMap

/** The three feedback sounds (generated by `tools/make_sounds.py`, under res/raw). */
enum class DriftSound {
    /** A shift, an expense or a deposit was saved. */
    SAVED,

    /** The goal was reached (once per event). */
    GOAL,

    /** An expense was captured while the app is open. */
    CAPTURED,
}

/**
 * Plays the feedback sounds: a [SoundPool] with two streams on the sonification usage, at a low
 * fixed volume. A sound is heard only when the "צלילים" switch is on AND the phone's ringer is in
 * its normal mode — never in silent or vibrate. One instance, owned by the app graph.
 *
 * The samples are loaded on the first [warmUp] (the main screen calls it when it opens), so a
 * process that only captures in the background never creates the pool.
 */
class SoundPlayer(private val context: Context, settings: SettingsStore, scope: CoroutineScope) {

    private val audio: AudioManager? = context.getSystemService(AudioManager::class.java)

    @Volatile private var enabled: Boolean = true
    @Volatile private var pool: SoundPool? = null
    private val sampleIds = ConcurrentHashMap<DriftSound, Int>()
    private val loaded: MutableSet<Int> = ConcurrentHashMap.newKeySet<Int>()

    init {
        scope.launch {
            settings.settings.map { it.feedbackSound }.distinctUntilChanged().collect { enabled = it }
        }
    }

    /** Creates the pool and starts loading the three samples (asynchronous); safe to call again. */
    @Synchronized
    fun warmUp() {
        if (pool != null) return
        val created = try {
            SoundPool.Builder()
                .setMaxStreams(MAX_STREAMS)
                .setAudioAttributes(
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                        .build(),
                )
                .build()
        } catch (e: RuntimeException) {
            return
        }
        created.setOnLoadCompleteListener { _, sampleId, status -> if (status == 0) loaded.add(sampleId) }
        sampleIds[DriftSound.SAVED] = created.load(context, R.raw.saved, 1)
        sampleIds[DriftSound.GOAL] = created.load(context, R.raw.goal, 1)
        sampleIds[DriftSound.CAPTURED] = created.load(context, R.raw.captured, 1)
        pool = created
    }

    /** Plays [sound] when sounds are switched on and the ringer is in normal mode; otherwise does nothing. */
    fun play(sound: DriftSound) {
        if (!enabled) return
        if (audio?.ringerMode != AudioManager.RINGER_MODE_NORMAL) return
        val current = pool ?: return
        val id = sampleIds[sound] ?: return
        if (id !in loaded) return
        runCatching { current.play(id, VOLUME, VOLUME, 1, 0, 1f) }
    }

    private companion object {
        const val MAX_STREAMS = 2
        const val VOLUME = 0.3f
    }
}
